@@ -16,4 +16,24 @@
 <div class="overlay hidden" id="upgradeOverlay"><div class="dialog upgrade-dialog"><div class="eyebrow">EVOLUTION AVAILABLE</div><h2 class="title" style="font-size:38px">CHOOSE A <em>MOD.</em></h2><p class="subtitle" style="margin-bottom:0">Your pattern adapts. Pick one upgrade.</p><div class="upgrade-grid" id="upgradeGrid"></div></div></div>
 <div class="overlay hidden" id="overOverlay"><div class="dialog gameover"><div class="eyebrow">SIGNAL LOST</div><h2 class="title">RUN<br><em>ENDED.</em></h2><p class="subtitle">The swarm reclaimed the sector. Every run makes the next one stronger.</p><div class="results"><div class="result"><span class="label">SURVIVED</span><strong id="finalTime">00:00</strong></div><div class="result"><span class="label">SCORE</span><strong id="finalScore">0</strong></div><div class="result"><span class="label">LEVEL</span><strong id="finalLevel">1</strong></div></div><button class="primary" id="retryBtn">RUN IT BACK</button><div class="fineprint">YOUR NEXT RUN STARTS NOW</div></div></div></div>
 <footer class="bottom"><div class="controls"><div class="control"><span class="kbd">W</span><span class="kbd">A</span><span class="kbd">S</span><span class="kbd">D</span><span>MOVE</span></div><div class="control"><span class="kbd">SPACE</span><span>DASH</span></div><div class="control"><span class="kbd">ESC</span><span>PAUSE</span></div></div><div class="bottom-right"><span class="ready">● SYSTEM ONLINE</span><span class="mobile-bottom-note">AUTO-FIRE ENGAGED</span></div></footer></main>
 <script>
+(()=>{
+const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d'),arena=$('arena');
+let W=800,H=500,dpr=1,last=0,mode='menu',elapsed=0,spawnTimer=0,fireTimer=0,dashTimer=0,dashTime=0,invuln=0,score=0,level=1,xp=0,xpNeed=8,wave=1,kills=0,shake=0;
+let player,enemies=[],bullets=[],enemyBullets=[],gems=[],particles=[],orbs=[],keys={},joy={x:0,y:0},pointer={x:0,y:0,active:false},upgrades={damage:1,rate:1,speed:1,pierce:0,magnet:1,maxHp:100,orbit:0};
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),hyp=(x,y)=>Math.hypot(x,y),fmt=n=>String(n).padStart(2,'0');
+function resize(){const r=arena.getBoundingClientRect(),ow=W,oh=H;W=r.width;H=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(player){player.x=clamp(player.x/W*W,22,W-22);player.y=clamp(player.y/H*H,22,H-22)}if(ow&&oh&&enemies.length){const sx=W/ow,sy=H/oh;for(const list of [enemies,bullets,enemyBullets,gems,particles])for(const o of list){o.x*=sx;o.y*=sy}}}
+new ResizeObserver(resize).observe(arena);resize();
+function newRun(){elapsed=0;spawnTimer=.45;fireTimer=.15;dashTimer=0;dashTime=0;invuln=0;score=0;level=1;xp=0;xpNeed=8;wave=1;kills=0;shake=0;enemies=[];bullets=[];enemyBullets=[];gems=[];particles=[];orbs=[];upgrades={damage:1,rate:1,speed:1,pierce:0,magnet:1,maxHp:100,orbit:0};player={x:W/2,y:H/2,r:8,hp:100,maxHp:100,vx:0,vy:0,aim:0};mode='playing';hideOverlays();updateHud();}
+function show(id){$(id).classList.remove('hidden')}function hide(id){$(id).classList.add('hidden')}function hideOverlays(){['startOverlay','pauseOverlay','upgradeOverlay','overOverlay'].forEach(hide)}
+$('startBtn').onclick=()=>newRun();$('retryBtn').onclick=()=>newRun();$('resumeBtn').onclick=()=>{mode='playing';hide('pauseOverlay')};$('pauseBtn').onclick=()=>togglePause();
+function togglePause(){if(mode==='playing'){mode='paused';show('pauseOverlay')}else if(mode==='paused'){$('resumeBtn').click()}}
+window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'||k==='p'){if(mode==='playing'||mode==='paused')togglePause()}if(k===' '&&mode==='playing')dash()});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left;pointer.y=e.clientY-r.top;pointer.active=true});canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'){const r=canvas.getBoundingClientRect();pointer.x=e.clientX-r.left;pointer.y=e.clientY-r.top;pointer.active=true}});
+function dash(){if(mode!=='playing'||dashTimer>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y;let m=hyp(dx,dy);if(m<.1){dx=Math.cos(player.aim);dy=Math.sin(player.aim);m=1}dx/=m;dy/=m;player.vx=dx*560;player.vy=dy*560;dashTimer=3.1;dashTime=.19;invuln=.32;burst(player.x,player.y,'#5be6d2',14,180)}$('dashTouch').addEventListener('pointerdown',e=>{e.preventDefault();dash()});
+const stick=$('stick'),knob=$('knob');let stickId=null;stick.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;stick.setPointerCapture(stickId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.min(34,hyp(dx,dy)),m=hyp(dx,dy)||1;joy.x=dx/m*d/34;joy.y=dy/m*d/34;knob.style.left=`calc(50% + ${joy.x*34}px)`;knob.style.top=`calc(50% + ${joy.y*34}px)`}function endStick(e){if(e.pointerId===stickId){stickId=null;joy.x=joy.y=0;knob.style.left=knob.style.top='50%'}}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);
+function updateHud(){ $('healthText').textContent=`${Math.ceil(player?.hp||100)} / ${player?.maxHp||100}`;$('healthFill').style.width=`${clamp((player?.hp||100)/(player?.maxHp||100)*100,0,100)}%`;$('levelText').textContent=fmt(level);$('xpText').textContent=`${xp} / ${xpNeed}`;$('xpFill').style.width=`${xp/xpNeed*100}%`;$('timeText').textContent=`${fmt(Math.floor(elapsed/60))}:${fmt(Math.floor(elapsed%60))}`;$('scoreText').textContent=String(score).padStart(4,'0');$('waveText').textContent=`WAVE ${fmt(wave)}`;$('waveSub').textContent=elapsed<8?'INCOMING':`${enemies.length} HOSTILES`}
+function burst(x,y,color,n=8,power=100){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.22,.6),max:.6,r:rand(1,3),color})}}
+function spawnEnemy(){const side=Math.floor(rand(0,4));let x=side===0?rand(0,W):side===1?W+15:side===2?rand(0,W):-15,y=side===0?-15:side===1?rand(0,H):side===2?H+15:rand(0,H);let t='chaser',r=7,hp=1,speed=rand(39,53),color='#ff765d';const roll=Math.random();if(elapsed>12&&roll<.20){t='runner';r=5;hp=1;speed=rand(74,92);color='#ffb45c'}else if(elapsed>20&&roll<.36){t='tank';r=12;hp=4+Math.floor(elapsed/80);speed=rand(23,31);color='#c078ff'}else if(elapsed>34&&roll<.49){t='shooter';r=8;hp=2;speed=rand(27,36);color='#ff5a9a'}let boss=elapsed>0&&Math.floor(elapsed/55)>Math.floor((elapsed-.8)/55);if(boss){t='boss';r=21;hp=26+Math.floor(elapsed/10);speed=25;color='#ff3e57'}enemies.push({x,y,r,hp,maxHp:hp,speed,type:t,color,phase:rand(0,7),shot:rand(.8,2),boss});if(boss){wave++;toast('ELITE SIGNAL DETECTED')} }
+function fire(){if(!enemies.length)return;let target=null,bd=Infinity;for(const e of enemies){let d=(e.x-player.x)**2+(e.y-player.y)**2;if(d<bd){bd=d;target=e}}if(!target)return;let a=Math.atan2(target.y-player.y,target.x-player.x);player.aim=a;let speed=440;bullets.push({x:player.x+Math.cos(a)*10,y:player.y+Math.sin(a)*10,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r:3.2,life:1.15,damage:upgrades.damage,pierce:upgrades.pierce,hit:[]});burst(player.x+Math.cos(a)*9,player.y+Math.sin(a)*9,'#b6fff1',2,45)}
+function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1050)}

