function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),1050)}
const modPool=[
 {id:'damage',icon:'✳',name:'HOTTER CORE',desc:'+35% projectile damage',apply:()=>upgrades.damage*=1.35},
 {id:'rate',icon:'»',name:'QUICK CYCLE',desc:'Fire 22% faster',apply:()=>upgrades.rate*=1.22},
 {id:'speed',icon:'↗',name:'AFTERBURN',desc:'+14% movement speed',apply:()=>upgrades.speed*=1.14},
 {id:'pierce',icon:'⌁',name:'PHASE ROUNDS',desc:'Shots pierce +1 target',apply:()=>upgrades.pierce++},
 {id:'health',icon:'♥',name:'REPAIR NANITES',desc:'Restore 35 hull and +10 max hull',apply:()=>{player.maxHp+=10;upgrades.maxHp=player.maxHp;player.hp=Math.min(player.maxHp,player.hp+35)}},
 {id:'magnet',icon:'◎',name:'DATA MAGNET',desc:'Collect data from farther away',apply:()=>upgrades.magnet*=1.45},
 {id:'orbit',icon:'◉',name:'GUARDIAN DOT',desc:'Add a damaging orbiting dot',apply:()=>upgrades.orbit++}
];
function levelUp(){level++;xp-=xpNeed;xpNeed=Math.ceil(xpNeed*1.28+3);mode='upgrade';show('upgradeOverlay');const grid=$('upgradeGrid');grid.innerHTML='';let options=[...modPool].sort(()=>Math.random()-.5).slice(0,3);for(const mod of options){const card=document.createElement('button');card.className='upgrade';card.innerHTML=`<div class="upgrade-icon">${mod.icon}</div><div class="upgrade-name">${mod.name}</div><div class="upgrade-desc">${mod.desc}</div>`;card.onclick=()=>{mod.apply();hide('upgradeOverlay');mode='playing';toast(mod.name+' INSTALLED');updateHud();if(xp>=xpNeed)levelUp()};grid.append(card)}toast('LEVEL UP')}
function hurt(amount){if(invuln>0||mode!=='playing')return;player.hp-=amount;invuln=.7;shake=7;burst(player.x,player.y,'#ff765d',8,110);if(player.hp<=0){player.hp=0;gameOver()}updateHud()}
function killEnemy(index){const e=enemies[index];if(!e)return;burst(e.x,e.y,e.color,e.boss?30:9,e.boss?220:120);score+=e.boss?500:e.type==='tank'?45:20;kills++;gems.push({x:e.x,y:e.y,r:e.boss?6:4,value:e.boss?5:1,vx:rand(-20,20),vy:rand(-20,20),color:e.boss?'#d9fa68':'#5be6d2'});if(e.boss){for(let i=0;i<4;i++)gems.push({x:e.x+rand(-25,25),y:e.y+rand(-25,25),r:4,value:1,vx:rand(-50,50),vy:rand(-50,50),color:'#5be6d2'});toast('ELITE ELIMINATED')}enemies.splice(index,1)}
function gameOver(){mode='over';$('finalTime').textContent=$('timeText').textContent;$('finalScore').textContent=score.toLocaleString();$('finalLevel').textContent=level;show('overOverlay')}
function update(dt){if(mode!=='playing')return;elapsed+=dt;wave=Math.max(wave,Math.floor(elapsed/55)+1);spawnTimer-=dt;fireTimer-=dt;dashTimer=Math.max(0,dashTimer-dt);dashTime=Math.max(0,dashTime-dt);invuln=Math.max(0,invuln-dt);shake=Math.max(0,shake-dt*20);if(spawnTimer<=0){spawnEnemy();spawnTimer=Math.max(.24,1.05-elapsed*.006)*rand(.72,1.23)}if(fireTimer<=0){fire();fireTimer=.34/upgrades.rate}
let ix=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,iy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y,im=hyp(ix,iy);if(im>1){ix/=im;iy/=im}if(dashTime>0){player.x+=player.vx*dt;player.y+=player.vy*dt}else{const sp=185*upgrades.speed;player.x+=ix*sp*dt;player.y+=iy*sp*dt;player.vx*=.8;player.vy*=.8}player.x=clamp(player.x,player.r+4,W-player.r-4);player.y=clamp(player.y,player.r+4,H-player.r-4);
for(let i=enemies.length-1;i>=0;i--){const e=enemies[i],dx=player.x-e.x,dy=player.y-e.y,d=hyp(dx,dy)||1;let vx=dx/d,vy=dy/d;if(e.type==='shooter'&&d<205){vx=-vx;vy=-vy}if(e.type==='runner'){let wob=Math.sin(elapsed*6+e.phase)*.45;const nx=vx*Math.cos(wob)-vy*Math.sin(wob),ny=vx*Math.sin(wob)+vy*Math.cos(wob);vx=nx;vy=ny}e.x+=vx*e.speed*dt;e.y+=vy*e.speed*dt;if(e.type==='shooter'){e.shot-=dt;if(e.shot<=0&&d<300){enemyBullets.push({x:e.x,y:e.y,vx:dx/d*145,vy:dy/d*145,r:3.5,life:2});e.shot=rand(1.35,2.1)}}if(d<e.r+player.r+2)hurt(e.boss?18: e.type==='tank'?13:9)}
for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let remove=b.life<=0||b.x< -20||b.x>W+20||b.y< -20||b.y>H+20;for(let j=enemies.length-1;j>=0&&!remove;j--){const e=enemies[j];if(b.hit.includes(e)||hyp(b.x-e.x,b.y-e.y)>b.r+e.r)continue;b.hit.push(e);e.hp-=b.damage;burst(b.x,b.y,e.color,3,40);if(e.hp<=0)killEnemy(j);if(b.pierce>0)b.pierce--;else remove=true}if(remove)bullets.splice(i,1)}
for(let i=enemyBullets.length-1;i>=0;i--){const b=enemyBullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0||b.x< -20||b.x>W+20||b.y< -20||b.y>H+20){enemyBullets.splice(i,1);continue}if(hyp(b.x-player.x,b.y-player.y)<b.r+player.r){enemyBullets.splice(i,1);hurt(10)}}
for(let i=gems.length-1;i>=0;i--){const g=gems[i],d=hyp(player.x-g.x,player.y-g.y);if(d<100*upgrades.magnet){let speed=105+(1-d/(100*upgrades.magnet))*360;g.x+=(player.x-g.x)/(d||1)*speed*dt;g.y+=(player.y-g.y)/(d||1)*speed*dt}else{g.x+=g.vx*dt;g.y+=g.vy*dt;g.vx*=.95;g.vy*=.95}if(d<player.r+g.r+4){xp+=g.value;score+=g.value*5;burst(g.x,g.y,g.color,5,75);gems.splice(i,1);if(xp>=xpNeed)levelUp()}}
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.96;p.vy*=.96;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
if(upgrades.orbit){for(let k=0;k<upgrades.orbit;k++){const a=elapsed*2.7+k*Math.PI*2/upgrades.orbit,ox=player.x+Math.cos(a)*25,oy=player.y+Math.sin(a)*25;for(let i=enemies.length-1;i>=0;i--){const e=enemies[i];if(hyp(ox-e.x,oy-e.y)<e.r+4){e.hp-=24*dt;if(e.hp<=0)killEnemy(i)}}}}
updateHud()}

